-- Read-only Supabase snapshot reproduced in disposable PostgreSQL 17.
-- This fixture is NOT the production schema. Only queried columns/triggers reproduced.
\set ON_ERROR_STOP on
CREATE SCHEMA saly;
CREATE SCHEMA visual;
CREATE SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

CREATE TABLE saly.proyecto (id bigint PRIMARY KEY,codigo text NOT NULL);
INSERT INTO saly.proyecto VALUES (2,'SALY-001');
CREATE TABLE saly.identity_elements (
 id bigint PRIMARY KEY,project_id bigint NOT NULL,code text NOT NULL UNIQUE,
 family text NOT NULL,value_type text NOT NULL
);
CREATE TABLE saly.identity_versions (
 id bigint PRIMARY KEY,element_id bigint NOT NULL REFERENCES saly.identity_elements(id),
 approval_status text NOT NULL,value_json jsonb NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE saly.creative_context_sets(
 id bigint PRIMARY KEY,project_id bigint NOT NULL,code text NOT NULL UNIQUE,
 version_label text NOT NULL,mode text NOT NULL DEFAULT 'EXPLORE',
 state text NOT NULL DEFAULT 'DRAFT',sealed_at timestamptz,
 provenance text NOT NULL
);
CREATE TABLE saly.creative_context_tokens(
 context_set_id bigint NOT NULL REFERENCES saly.creative_context_sets(id),
 identity_version_id bigint NOT NULL REFERENCES saly.identity_versions(id),
 role text NOT NULL CHECK(role IN ('OFFICIAL','EXISTING','HOME')),
 value_sha256 text NOT NULL,
 PRIMARY KEY(context_set_id,identity_version_id)
);
CREATE TABLE saly.creative_orders (
 id bigint PRIMARY KEY,project_id bigint NOT NULL,code text NOT NULL,
 request_kind text NOT NULL,design_mode text NOT NULL,status text NOT NULL,
 context_set_id bigint REFERENCES saly.creative_context_sets(id),
 identity_snapshot jsonb NOT NULL,scope_json jsonb NOT NULL
);
CREATE TABLE saly.creative_order_items (
 id bigint PRIMARY KEY,order_id bigint NOT NULL REFERENCES saly.creative_orders(id),
 code text NOT NULL,status text NOT NULL,context_json jsonb NOT NULL,
 acceptance_json jsonb NOT NULL,qa_receipt jsonb NOT NULL,
 kind text NOT NULL,ordinal integer NOT NULL,
 variant_of_item_id bigint,required boolean NOT NULL,
 approved_at timestamptz,approved_by text
);
CREATE TABLE saly.creative_runs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id bigint NOT NULL,item_id bigint NOT NULL);
CREATE TABLE saly.creative_item_dependencies(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id bigint NOT NULL,item_id bigint NOT NULL,depends_on_item_id bigint NOT NULL);
CREATE TABLE saly.creative_item_sources(item_id bigint NOT NULL,order_id bigint NOT NULL,source_asset_id bigint NOT NULL,source_sha256 text NOT NULL,purpose text);
CREATE TABLE visual.source_assets (
 id bigint PRIMARY KEY,asset_code text,source_kind text,provider text,file_ref text,
 source_sha256 text,independent_sha_verified boolean,brand_code text,approval_status text
);
