(7,2,'SALY_HOME_V015_SINGLE_20261123','APP_SCREEN_SINGLE','EXPLORE','TERMINADO',3,'{"context_set_id":3,"selected_versions":[{"role":"OFFICIAL","sha256":"f52bd036b0760f64f6222f25d95ebe0c56859cbef34dec923c7af8cd5c09ca52","version_id":7},{"role":"OFFICIAL","sha256":"e0bc5fc47e1f2fa3bdd1d51b34356594a0ee88d39d107562cd7a4a2d1de27b7f","version_id":8},{"role":"EXISTING","sha256":"57822661b02310f97ccd242ce929ed82907251ef22f350f9673d76c56c918a13","version_id":11},{"role":"EXISTING","sha256":"0719a985e5f09e61620906078676ecfe93c63810dca870702b834754d1b7046c","version_id":12},{"role":"EXISTING","sha256":"9a003c868816e05d0858815160d14524fdbd037ac9e92c794261e89a4cc48299","version_id":14},{"role":"EXISTING","sha256":"935bfe20fac036b1ab0a772616d84780171634a84700ef985f06a49a0573dbf2","version_id":18},{"role":"HOME","sha256":"6028d40a3ecbf812fd8bcfb3306c6afc6826535b6a59aa22ef4f4a83cfac9580","version_id":57}]}'::jsonb,'{"screen":"HOME","ordinal":1,"queue_mode":"SERIAL_V1","review_only":true,"block_reason":"NATIVE_DISPATCH_NOT_DEPLOYED","prompt_sha256":"13aac045a189b4f2dd085bf43e94f395666a20e7cc5ce87e596499c4a9100fd6","prompt_source":"SALY_V015_GATE_REAL_REVIEW_ONLY","compiled_prompt":"Destino visual: Un iPhone 16 Pro con pantalla home SALY\nUna pantalla SALY sin cifras inventadas.\nHome SALY en iPhone 16 Pro frontal, estudio gris casi blanco; cabecera blanca reservada al logo oficial del compositor, sin recrearlo.\nFintech sobria, verde #008200 solo para CTA y menta #EAF9EE, crema #FFF9E9, lavanda #F4E7FD como acentos suaves de categorías.\nFondo de aplicación blanco con secciones suaves y sin contenedores redundantes.\nMonto dominante y etiquetas legibles sin saltos incómodos.\nDisponible y Solicitar adelanto primero; resumen en dos columnas, con Mi disponible / Cómo se calcula abajo.\nSin ilustración junto al saldo ni filas de iconos aislados.\nConcepto compositivo seleccionado: Dos datos en grupos equilibrados, iconos laterales y acceso a cálculo en franja inferior\nDisponible para adelanto con el monto protagonista y CTA Solicitar adelanto, sin valores inventados\nSaly Plus: hasta 3 días antes y sorteos para ganar efectivo; Saly Rewards: Tus buenos hábitos te hacen ganar dinero; Beneficios: Descubre más.\nPróximo descuento e Importe estimado en dos grupos; Mi disponible / Cómo se calcula integrado debajo.\nDisponible y acción: Mostrar monto libre de adornos y un CTA primario.\nResumen financiero: Fecha e importe con icono lateral; explicación abajo, sin fila de iconos.\nDescubre más en Saly: Tres categorías con textos breves en superficies tonales distintas.\nNavegación: Barra inferior Inicio, Historial, Explorar, Perfil; Inicio activo discreto.\nNo agregar rayos de explosión, palitos de énfasis, destellos radiales ni líneas cinéticas decorativas alrededor de iconos, montos, botones o ilustraciones. Mantener solamente trazos funcionales de iconografía y separadores estructurales justificados.","render_authorized":false,"intake_semantic_qa":{"verdict":"BLOCKED","intent_class":"OPERATIONAL_PROCESS_INSTRUCTION","source_origin":"PR4648_SOURCE_SEED","source_sha256":"835c6c243a95d651b473527bf92cb742067897916351919e408d3e5f0d868a3a","blocking_reason":"CREATIVE_USER_LITERAL_NOT_RECOVERED","repair_contract":"SALY_CREATIVE_INTAKE_SEMANTIC_REPAIR_V1","compiled_prompt_origin":"ASSISTANT_DERIVED_REVIEW_NOT_USER_LITERAL"},"rendering_authority":false,"intake_source_status":"MISSING_VERIFIED_USER_VISUAL_REQUEST","operational_instruction":"No, pero igual eso causa problema. Lo que debemos demandar es solo un pedido con una, o sea, la pantalla de Ergon que termine la pantalla de home y después haces la otra pantalla. Si no va a haber tendencia al error"}'::jsonb),
(8,2,'SALY_ADELANTO_V015_SINGLE_20261123','APP_SCREEN_SINGLE','EXPLORE','PLANIFICADO',4,'{"context_set_id":4,"selected_versions":[{"role":"OFFICIAL","sha256":"f52bd036b0760f64f6222f25d95ebe0c56859cbef34dec923c7af8cd5c09ca52","version_id":7},{"role":"OFFICIAL","sha256":"e0bc5fc47e1f2fa3bdd1d51b34356594a0ee88d39d107562cd7a4a2d1de27b7f","version_id":8},{"role":"EXISTING","sha256":"57822661b02310f97ccd242ce929ed82907251ef22f350f9673d76c56c918a13","version_id":11},{"role":"EXISTING","sha256":"0719a985e5f09e61620906078676ecfe93c63810dca870702b834754d1b7046c","version_id":12},{"role":"EXISTING","sha256":"9a003c868816e05d0858815160d14524fdbd037ac9e92c794261e89a4cc48299","version_id":14}]}'::jsonb,'{"screen":"SOLICITAR_ADELANTO","ordinal":2,"queue_mode":"SERIAL_V1","review_only":true,"block_reason":"NATIVE_DISPATCH_NOT_DEPLOYED","prompt_sha256":"c77ce1be1a09aa64b7ab833c1207cc116b22cbe45682e5a7fe611abb5eb54f50","prompt_source":"SALY_V015_GATE_REAL_REVIEW_ONLY","compiled_prompt":"Destino visual: Un iPhone 16 Pro con pantalla solicitar SALY\nUna pantalla SALY sin cifras inventadas.\nSolicitar adelanto SALY, iPhone 16 Pro frontal en modo claro.\nCTA verde #008200, montos navy #081631, resto neutro; evitar verde omnipresente.\nDisponible sobre franja menta #EAF9EE integrada al fondo, sin tarjeta adicional.\nDiferenciar monto elegido y monto a recibir por tamaño, etiqueta y posición.\nJerarquía: disponible, selección, resumen y CTA Continuar.\nSelección con borde y marcador funcional; no insinuar recomendación económica.\nConcepto compositivo seleccionado: Franja tonal de disponible, selección agrupada, resumen abierto y CTA final\nTres opciones de monto y entrada manual bajo Cuánto necesitas, sin números ficticios.\nMonto solicitado, Cargos aplicables, Monto a recibir y Fecha de descuento sólo si hay valores respaldados.\nContinuar en CTA verde #008200 con texto blanco; no etiquetar Recomendado sin regla autorizada.\nCabecera: Volver, título Solicitar adelanto y ayuda sobre blanco.\nDisponible: Franja menta integrada, sin contenedor redundante.\nMonto: Tres opciones seleccionables, borde e indicador; entrada manual.\nResumen: Monto a recibir destacado sin tarifas imaginarias.\nContinuar: Un CTA primario Continuar al final.\nNo agregar rayos de explosión, palitos de énfasis, destellos radiales ni líneas cinéticas decorativas alrededor de iconos, montos, botones o ilustraciones. Mantener solamente trazos funcionales de iconografía y separadores estructurales justificados.","render_authorized":false,"intake_semantic_qa":{"verdict":"BLOCKED","intent_class":"OPERATIONAL_PROCESS_INSTRUCTION","source_origin":"PR4648_SOURCE_SEED","source_sha256":"835c6c243a95d651b473527bf92cb742067897916351919e408d3e5f0d868a3a","blocking_reason":"CREATIVE_USER_LITERAL_NOT_RECOVERED","repair_contract":"SALY_CREATIVE_INTAKE_SEMANTIC_REPAIR_V1","compiled_prompt_origin":"ASSISTANT_DERIVED_REVIEW_NOT_USER_LITERAL"},"rendering_authority":false,"intake_source_status":"MISSING_VERIFIED_USER_VISUAL_REQUEST","operational_instruction":"No, pero igual eso causa problema. Lo que debemos demandar es solo un pedido con una, o sea, la pantalla de Ergon que termine la pantalla de home y después haces la otra pantalla. Si no va a haber tendencia al error"}'::jsonb),
