A","refinement_of_item_id":10,"refinement_of_order_id":7,"dependency_policy_state":"UNRESOLVED_IMMUTABLE_SUCCESSOR_CHAIN","preview_artifact_sha256":"8854a525b61d5642b3e864d5f35dbd9e3fdaf1bab83754ddeaa884eaf90f52d0","source_verification_status":"USER_EXCERPT_AVAILABLE_MESSAGE_ID_NOT_VERIFIED","no_changes_to_other_components":true}'::jsonb);
