(13,9,'HOME_MIDISPONIBLE','PENDIENTE','{"screen_spec":{"device":"IPHONE16PRO","screen":"HOME"},"parent_item_id":10,"parent_order_id":7,"target_component":"HOME.SUMMARY.MI_DISPONIBLE"}'::jsonb,'{"assertions":["Mi disponible is a navigation entry to Cómo se calcula","Do not render a standalone monetary value in Mi disponible","All other HOME regions and their copy unchanged"],"qa_required":true,"semantic_qa":{"status":"PENDING"}}'::jsonb,'{}'::jsonb,'SCREEN',1,NULL,true,NULL,NULL);
CREATE VIEW saly.v_identity_current AS
SELECT 'SALY-001'::text AS project_code,v.id AS version_id
FROM saly.identity_versions v WHERE v.approval_status='APPROVED';
-- Original functions fetched directly from pg_get_functiondef, not re-authored.
CREATE OR REPLACE FUNCTION saly.creative_context_set_guard_l2a()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly', 'extensions'
AS $function$
DECLARE v_all int; v_official int; v_drift int; v_distinct_codes int;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CREATIVE_CONTEXT_SET_DELETE_FORBIDDEN'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state='SEALED' THEN RAISE EXCEPTION 'CREATIVE_CONTEXT_SET_IMMUTABLE'; END IF;
  IF NEW.project_id IS DISTINCT FROM OLD.project_id
   OR NEW.code IS DISTINCT FROM OLD.code
   OR NEW.version_label IS DISTINCT FROM OLD.version_label
   OR NEW.mode IS DISTINCT FROM OLD.mode
   OR NEW.provenance IS DISTINCT FROM OLD.provenance
  THEN RAISE EXCEPTION 'CREATIVE_CONTEXT_IDENTITY_IMMUTABLE'; END IF;
 END IF;
 IF NEW.state='SEALED' THEN
  -- OLD is read only in the UPDATE-only guard above.
  -- Universal seal rule: two effective SALY official colors, no duplicate codes,
  -- verified immutable values; no 41-token hardcode for future EXPLORE sets.
  SELECT count(*)::int,
    count(*) FILTER(WHERE t.role='OFFICIAL')::int,
    count(DISTINCT e.code)::int,
    count(*) FILTER(WHERE t.value_sha256<>encode(extensions.digest(v.value_json::text,'sha256'),'hex'))::int
  INTO v_all,v_official,v_distinct_codes,v_drift
  FROM saly.creative_context_tokens t
  JOIN saly.identity_versions v ON v.id=t.identity_version_id
  JOIN saly.identity_elements e ON e.id=v.element_id
  WHERE t.context_set_id=NEW.id;
  IF v_all<2 OR v_official<>2 OR v_all<>v_distinct_codes OR v_drift<>0
  THEN RAISE EXCEPTION 'CREATIVE_CONTEXT_SEAL_INCOMPLETE_DUPLICATE_OR_DRIFT'; END IF;
  IF EXISTS (
    SELECT 1 FROM saly.creative_context_tokens t
    WHERE t.context_set_id=NEW.id AND t.role='OFFICIAL'
    AND NOT EXISTS (SELECT 1 FROM saly.v_identity_current effective
       WHERE effective.project_code='SALY-001'
       AND effective.version_id=t.identity_version_id))
  THEN RAISE EXCEPTION 'CREATIVE_CONTEXT_OFFICIAL_NOT_EFFECTIVE'; END IF;
  IF EXISTS (
   SELECT 1 FROM saly.creative_context_tokens alias_link
   JOIN saly.identity_versions alias_v ON alias_v.id=alias_link.identity_version_id
   WHERE alias_link.context_set_id=NEW.id
    AND alias_v.metadata->>'kind'='ALIAS'
    AND NOT EXISTS (
       SELECT 1 FROM saly.creative_context_tokens target_link
       JOIN saly.identity_versions target_v ON target_v.id=target_link.identity_version_id
       JOIN saly.identity_elements target_e ON target_e.id=target_v.element_id
       WHERE target_link.context_set_id=NEW.id
        AND target_e.code=alias_v.metadata->>'alias_target_code'))
  THEN RAISE EXCEPTION 'CREATIVE_CONTEXT_ALIAS_TARGET_MISSING'; END IF;
  NEW.sealed_at:=now();
 END IF;
 RETURN NEW;
END $function$

;

CREATE OR REPLACE FUNCTION saly.creative_context_token_guard_l2a()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly', 'extensions'
AS $function$
DECLARE v_set record; v_version record; v_expected_role text;
BEGIN
 IF TG_OP<>'INSERT' THEN
   RAISE EXCEPTION 'CREATIVE_CONTEXT_TOKEN_IMMUTABLE';
 END IF;
 SELECT * INTO v_set FROM saly.creative_context_sets WHERE id=NEW.context_set_id FOR UPDATE;
 IF NOT FOUND OR v_set.state<>'DRAFT' THEN
   RAISE EXCEPTION 'CREATIVE_CONTEXT_NOT_DRAFT';
 END IF;
 SELECT e.project_id,e.code,v.approval_status,v.value_json INTO v_version
 FROM saly.identity_versions v JOIN saly.identity_elements e ON e.id=v.element_id
 WHERE v.id=NEW.identity_version_id;
 IF NOT FOUND OR v_version.project_id<>v_set.project_id THEN
   RAISE EXCEPTION 'CREATIVE_CONTEXT_WRONG_PROJECT_OR_VERSION';
 END IF;
 v_expected_role:=CASE
  WHEN v_version.code IN ('color.brand.primary','color.action.primary.bg')
       AND v_version.approval_status='APPROVED' THEN 'OFFICIAL'
  WHEN v_version.code LIKE 'candidate.saly_ds_v1.%'
       AND v_version.approval_status='CANDIDATE' THEN 'EXISTING'
  WHEN v_version.code LIKE 'candidate.saly_home_v3.%'
       AND v_version.approval_status='CANDIDATE' THEN 'HOME'
  ELSE NULL END;
 IF v_expected_role IS NULL OR NEW.role<>v_expected_role THEN
   RAISE EXCEPTION 'CREATIVE_CONTEXT_ROLE_NOT_AUTHORIZED';
 END IF;
 NEW.value_sha256:=encode(extensions.digest(v_version.value_json::text,'sha256'),'hex');
 RETURN NEW;
END $function$

;

CREATE OR REPLACE FUNCTION saly.creative_order_context_guard_l2a()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly'
AS $function$
DECLARE v_context record; v_tokens jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN
   IF OLD.status<>'BORRADOR'
      AND (NEW.context_set_id IS DISTINCT FROM OLD.context_set_id
       OR NEW.identity_snapshot IS DISTINCT FROM OLD.identity_snapshot)
   THEN RAISE EXCEPTION 'CREATIVE_ORDER_CONTEXT_FROZEN'; END IF;
 END IF;
 IF NEW.status<>'BORRADOR' THEN
  SELECT project_id,mode,state INTO v_context FROM saly.creative_context_sets
  WHERE id=NEW.context_set_id;
  IF NOT FOUND OR v_context.project_id<>NEW.project_id
   OR v_context.mode<>NEW.design_mode OR v_context.state<>'SEALED'
  THEN RAISE EXCEPTION 'CREATIVE_ORDER_CONTEXT_NOT_SEALED'; END IF;
  IF TG_OP='INSERT' THEN
    SELECT jsonb_agg(jsonb_build_object('version_id',identity_version_id,
      'sha256',value_sha256,'role',role) ORDER BY identity_version_id)
    INTO v_tokens
    FROM saly.creative_context_tokens WHERE context_set_id=NEW.context_set_id;
    NEW.identity_snapshot:=jsonb_build_object('context_set_id',NEW.context_set_id,
      'selected_versions',v_tokens);
  ELSIF OLD.status='BORRADOR' THEN
    SELECT jsonb_agg(jsonb_build_object('version_id',identity_version_id,
      'sha256',value_sha256,'role',role) ORDER BY identity_version_id)
    INTO v_tokens
    FROM saly.creative_context_tokens WHERE context_set_id=NEW.context_set_id;
    NEW.identity_snapshot:=jsonb_build_object('context_set_id',NEW.context_set_id,
      'selected_versions',v_tokens);
  END IF;
 END IF;
 RETURN NEW;
END $function$

;

CREATE OR REPLACE FUNCTION saly.creative_chat_terminal_item_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly', 'pg_temp'
AS $function$
DECLARE
  v_j jsonb;
  v_a jsonb;
  v_order_status text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status='TERMINADO' OR EXISTS (
   SELECT 1 FROM saly.creative_orders o WHERE o.id=OLD.order_id AND o.status='TERMINADO'
  ) THEN RAISE EXCEPTION 'SALY_CHAT_TERMINAL_ITEM_IMMUTABLE'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP<>'UPDATE' THEN RETURN NEW; END IF;
 SELECT status INTO v_order_status FROM saly.creative_orders
 WHERE id=NEW.order_id FOR UPDATE;
 IF OLD.status='TERMINADO' OR v_order_status='TERMINADO' THEN
  RAISE EXCEPTION 'SALY_CHAT_TERMINAL_ITEM_IMMUTABLE'; END IF;
 IF NEW.status='TERMINADO' AND OLD.status IS DISTINCT FROM NEW.status THEN
  IF OLD.status<>'PENDIENTE' OR NEW.order_id<>OLD.order_id
  OR NEW.code<>OLD.code OR NEW.acceptance_json IS DISTINCT FROM OLD.acceptance_json
  OR NEW.context_json IS DISTINCT FROM OLD.context_json
  OR EXISTS (SELECT 1 FROM saly.creative_runs r WHERE r.item_id=NEW.id)
  THEN RAISE EXCEPTION 'SALY_CHAT_TERMINAL_NOT_ARCHIVED_PENDING'; END IF;
  v_a:=OLD.qa_receipt->'chat_artifact_reconciliation_v1';
  v_j:=NEW.qa_receipt->'chat_judge_v1';
  IF v_a IS NULL OR v_j IS NULL
  OR NEW.qa_receipt->'chat_artifact_reconciliation_v1' IS DISTINCT FROM v_a
  OR v_a->>'status' IS DISTINCT FROM 'ENTREGADO_EN_CHAT_PENDIENTE_QA_INDEPENDIENTE'
  OR v_a->>'avoid_regeneration' IS DISTINCT FROM 'true'
  OR v_a->>'chat_delivery_observed' IS DISTINCT FROM 'true'
  OR v_a->>'sha256' !~ '^[0-9a-f]{64}$'
  OR v_j->>'artifact_sha256' IS DISTINCT FROM v_a->>'sha256'
  OR v_j->>'judge_receipt_sha256' !~ '^[0-9a-f]{64}$'
  OR v_j->>'source_manifest_input_sha256' !~ '^[0-9a-f]{64}$'
  OR v_j->>'judge_kind' IS DISTINCT FROM 'DETERMINISTIC_TECHNICAL_SEPARATE_PROCESS'
  OR v_j->>'technical_verdict' NOT IN ('PASS_TECHNICAL','PASS_TECHNICAL_WITH_OBSERVATIONS')
  OR v_j->>'technical_verdict' IS NULL
  OR v_j->>'semantic_independence_proven' IS DISTINCT FROM 'false'
  OR v_j->>'semantic_verdict' IS DISTINCT FROM 'NOT_INDEPENDENTLY_EVALUATED'
  OR v_j->>'production_approved' IS DISTINCT FROM 'false'
  OR v_j->>'run_verified' IS DISTINCT FROM 'false'
  OR v_j->>'terminal_semantics' IS DISTINCT FROM 'IMAGE_DELIVERED_AND_QA_COMMENTED_NOT_APPROVED'
  OR nullif(btrim(v_j->>'qa_comment'),'') IS NULL
  OR jsonb_typeof(v_j->'observations') IS DISTINCT FROM 'array'
  OR NEW.approved_at IS NOT NULL OR NEW.approved_by IS NOT NULL
  OR EXISTS (
    SELECT 1 FROM saly.creative_item_dependencies d
    JOIN saly.creative_order_items p ON p.id=d.depends_on_item_id
    WHERE d.order_id=NEW.order_id AND d.item_id=NEW.id
      AND p.status NOT IN ('TERMINADO','APROBADO')
  ) THEN
   RAISE EXCEPTION 'SALY_CHAT_TERMINAL_JUDGE_OR_DEPENDENCY_MISSING';
  END IF;
 END IF;
 RETURN NEW;
END $function$

;

CREATE OR REPLACE FUNCTION saly.creative_single_screen_item_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'saly', 'pg_temp'
AS $function$
DECLARE kind_of_order text;
BEGIN
 SELECT request_kind INTO kind_of_order FROM saly.creative_orders
 WHERE id=NEW.order_id FOR UPDATE;
 IF kind_of_order IS DISTINCT FROM 'APP_SCREEN_SINGLE' THEN RETURN NEW; END IF;
 IF NEW.kind IS DISTINCT FROM 'SCREEN' OR NEW.ordinal IS DISTINCT FROM 1
 OR NEW.variant_of_item_id IS NOT NULL
 THEN RAISE EXCEPTION 'CREATIVE_SINGLE_SCREEN_ITEM_SHAPE'; END IF;
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id
  OR NEW.order_id IS DISTINCT FROM OLD.order_id
  OR NEW.code IS DISTINCT FROM OLD.code)
 THEN RAISE EXCEPTION 'CREATIVE_SINGLE_SCREEN_ITEM_BINDING_IMMUTABLE'; END IF;
 IF TG_OP='INSERT' AND EXISTS (SELECT 1 FROM saly.creative_order_items
   WHERE order_id=NEW.order_id)
 THEN RAISE EXCEPTION 'CREATIVE_SINGLE_SCREEN_MULTIPLE_ITEMS'; END IF;
 RETURN NEW;
END $function$

;

CREATE OR REPLACE FUNCTION saly.creative_item_context_l2a(p_item_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'saly', 'visual', 'extensions'
AS $function$
DECLARE v_item record; v_tokens jsonb; v_refs jsonb; v_expected_snapshot jsonb; v_needed int; v_found int; v_drift int;
BEGIN
 SELECT i.id,i.code,i.context_json,o.id AS order_id,o.context_set_id,o.design_mode,
   o.status AS order_status,o.identity_snapshot AS order_snapshot,
   ctx.state AS context_state,p.codigo AS project_code
 INTO v_item FROM saly.creative_order_items i
 JOIN saly.creative_orders o ON o.id=i.order_id
 JOIN saly.proyecto p ON p.id=o.project_id
 LEFT JOIN saly.creative_context_sets ctx ON ctx.id=o.context_set_id
 WHERE i.id=p_item_id;
 IF NOT FOUND OR v_item.project_code<>'SALY-001' OR v_item.context_set_id IS NULL
 THEN RAISE EXCEPTION 'CREATIVE_ITEM_CONTEXT_UNAVAILABLE'; END IF;
 IF v_item.order_status NOT IN ('PLANIFICADO','EN_PROCESO','EN_QA')
   OR v_item.context_state IS DISTINCT FROM 'SEALED'
   OR v_item.design_mode<>'EXPLORE'
 THEN RAISE EXCEPTION 'CREATIVE_ITEM_CONTEXT_NOT_ADMITTED'; END IF;
 SELECT jsonb_agg(jsonb_build_object('version_id',identity_version_id,
    'sha256',value_sha256,'role',role) ORDER BY identity_version_id)
 INTO v_expected_snapshot
 FROM saly.creative_context_tokens WHERE context_set_id=v_item.context_set_id;
 IF v_expected_snapshot IS NULL OR
    v_item.order_snapshot IS DISTINCT FROM jsonb_build_object(
      'context_set_id',v_item.context_set_id,'selected_versions',v_expected_snapshot)
 THEN RAISE EXCEPTION 'CREATIVE_ITEM_CONTEXT_SNAPSHOT_MISMATCH'; END IF;
 IF v_item.context_json ? 'token_codes'
    AND jsonb_typeof(v_item.context_json->'token_codes')<>'array'
 THEN RAISE EXCEPTION 'CREATIVE_ITEM_TOKEN_SELECTION_INVALID'; END IF;
 -- Candidate tokens are opt-in per screen; official tokens always included.
 WITH requested AS (
  SELECT DISTINCT jsonb_array_elements_text(
    COALESCE(v_item.context_json->'token_codes','[]'::jsonb)) AS code
 )
 SELECT count(*)::int INTO v_needed FROM requested;
 WITH requested AS (
  SELECT DISTINCT jsonb_array_elements_text(
    COALESCE(v_item.context_json->'token_codes','[]'::jsonb)) AS code
 ), available AS (
  SELECT e.code,t.role FROM saly.creative_context_tokens t
  JOIN saly.identity_versions v ON v.id=t.identity_version_id
  JOIN saly.identity_elements e ON e.id=v.element_id
  WHERE t.context_set_id=v_item.context_set_id
 )
 SELECT count(*)::int INTO v_found
 FROM requested r JOIN available a ON a.code=r.code;
 IF v_needed<>v_found THEN RAISE EXCEPTION 'CREATIVE_ITEM_TOKEN_NOT_IN_LOCKED_CONTEXT'; END IF;
 SELECT count(*)::int INTO v_drift FROM saly.creative_context_tokens t
 JOIN saly.identity_versions v ON v.id=t.identity_version_id
 WHERE t.context_set_id=v_item.context_set_id
 AND t.value_sha256<>encode(extensions.digest(v.value_json::text,'sha256'),'hex');
 IF v_drift<>0 THEN RAISE EXCEPTION 'CREATIVE_ITEM_TOKEN_VERSION_DRIFT'; END IF;
 WITH requested AS (
  SELECT DISTINCT jsonb_array_elements_text(
    COALESCE(v_item.context_json->'token_codes','[]'::jsonb)) AS code
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('code',e.code,'role',t.role,
   'version_id',v.id,'value_json',v.value_json,'value_sha256',t.value_sha256)
   ORDER BY e.code),'[]'::jsonb)
 INTO v_tokens
 FROM saly.creative_context_tokens t
 JOIN saly.identity_versions v ON v.id=t.identity_version_id
 JOIN saly.identity_elements e ON e.id=v.element_id
 WHERE t.context_set_id=v_item.context_set_id AND
   (t.role='OFFICIAL' OR e.code IN (SELECT code FROM requested)
   OR e.code IN (
       SELECT DISTINCT alias_v.metadata->>'alias_target_code'
       FROM saly.creative_context_tokens alias_link
       JOIN saly.identity_versions alias_v ON alias_v.id=alias_link.identity_version_id
       JOIN saly.identity_elements alias_e ON alias_e.id=alias_v.element_id
       WHERE alias_link.context_set_id=v_item.context_set_id
        AND alias_e.code IN (SELECT code FROM requested)
        AND alias_v.metadata->>'kind'='ALIAS')
   );
 IF EXISTS (SELECT 1 FROM saly.creative_item_sources s
   JOIN visual.source_assets a ON a.id=s.source_asset_id
   WHERE s.item_id=v_item.id AND s.order_id=v_item.order_id
     AND (s.source_sha256 IS DISTINCT FROM a.source_sha256
       OR NOT a.independent_sha_verified OR a.brand_code<>'SALY'
       OR a.approval_status NOT IN ('CANDIDATE','APPROVED')))
 THEN RAISE EXCEPTION 'CREATIVE_ITEM_SOURCE_REFERENCE_DRIFT'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('asset_id',a.id,
  'asset_code',a.asset_code,'source_kind',a.source_kind,
  'provider',a.provider,'file_ref',a.file_ref,
  'source_sha256',s.source_sha256,'approval_status',a.approval_status,
  'purpose',s.purpose) ORDER BY a.asset_code),'[]'::jsonb)
 INTO v_refs
 FROM saly.creative_item_sources s JOIN visual.source_assets a ON a.id=s.source_asset_id
 WHERE s.item_id=v_item.id AND s.order_id=v_item.order_id;
 RETURN jsonb_build_object('schema_version','SALY_CREATIVE_CONTEXT_L2A',
  'business_code','SALY','project_code',v_item.project_code,
  'order_id',v_item.order_id,'item_id',v_item.id,'item_code',v_item.code,
  'design_mode',v_item.design_mode,'context_set_id',v_item.context_set_id,
  'tokens',v_tokens,'source_refs',v_refs,
  'image_generation_allowed',false,'visual_standard_status','NOT_ACTIVATED_BY_THIS_CONTEXT');
END $function$

;

CREATE TRIGGER trg_creative_context_set_guard_l2a
BEFORE INSERT OR UPDATE OR DELETE ON saly.creative_context_sets
FOR EACH ROW EXECUTE FUNCTION saly.creative_context_set_guard_l2a();
CREATE TRIGGER trg_creative_context_token_guard_l2a
BEFORE INSERT OR UPDATE OR DELETE ON saly.creative_context_tokens
FOR EACH ROW EXECUTE FUNCTION saly.creative_context_token_guard_l2a();
CREATE TRIGGER trg_creative_order_context_guard_l2a
BEFORE INSERT OR UPDATE ON saly.creative_orders
FOR EACH ROW EXECUTE FUNCTION saly.creative_order_context_guard_l2a();
CREATE TRIGGER trg_saly_creative_chat_terminal_item_guard_v1
BEFORE UPDATE OR DELETE ON saly.creative_order_items
FOR EACH ROW EXECUTE FUNCTION saly.creative_chat_terminal_item_guard_v1();
CREATE TRIGGER trg_creative_00_single_screen_item_guard_v1
BEFORE INSERT OR UPDATE ON saly.creative_order_items
FOR EACH ROW EXECUTE FUNCTION saly.creative_single_screen_item_guard_v1();

DO $baseline$
BEGIN
 IF (SELECT COUNT(*) FROM saly.identity_versions)<>55
 OR (SELECT COUNT(*) FROM saly.creative_context_tokens WHERE context_set_id=3)<>7
 OR (SELECT COUNT(*) FROM saly.creative_context_tokens WHERE context_set_id=4)<>5
 OR (SELECT COUNT(*) FROM saly.creative_orders WHERE id IN(7,8,9))<>3
 OR (SELECT COUNT(*) FROM saly.creative_order_items WHERE id IN(10,11,13))<>3
 THEN RAISE EXCEPTION 'LIVE_SNAPSHOT_FIXTURE_BASELINE_MISMATCH'; END IF;
END $baseline$;
